CREATE DATABASE IF NOT EXISTS yummy_flavors_db;
USE yummy_flavors_db;

CREATE TABLE `contacts` (
  `id` int(11) NOT NULL,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `gender` varchar(10) NOT NULL,
  `mobile` varchar(15) NOT NULL,
  `dob` date NOT NULL,
  `email` varchar(100) NOT NULL,
  `language` varchar(20) NOT NULL,
  `message` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `favorites` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `site_recipe_id` int(11) DEFAULT NULL,
  `recipe_name` varchar(255) NOT NULL,
  `recipe_image` text DEFAULT NULL,
  `recipe_url` text DEFAULT NULL,
  `category` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `recipes` (
  `id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `recipe_title` varchar(100) NOT NULL,
  `category` varchar(50) NOT NULL,
  `minutes` int(11) NOT NULL,
  `description` text NOT NULL,
  `photo_name` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `site_recipes` (
  `id` int(11) NOT NULL,
  `recipe_title` varchar(255) NOT NULL,
  `category` varchar(50) NOT NULL,
  `minutes` int(11) DEFAULT 30,
  `servings` varchar(50) DEFAULT NULL,
  `recipe_image` text NOT NULL,
  `recipe_url` text NOT NULL,
  `description` text DEFAULT NULL,
  `ingredients` longtext DEFAULT NULL,
  `instructions` longtext DEFAULT NULL,
  `search_text` longtext NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `site_recipes` (`id`, `recipe_title`, `category`, `minutes`, `servings`, `recipe_image`, `recipe_url`, `description`, `ingredients`, `instructions`, `search_text`, `created_at`) VALUES
(3, 'Old Fashioned Creamed Goldenrod Eggs', 'Breakfast', 35, '4 Servings', '/assets/img/recipes/breakfast/b1.jpg', '/recipes/breakfast/B1.html', 'These old fashioned creamed goldenrod eggs are warm and creamy, served over toast, and finished with grated egg yolk, crispy bacon crumbles, and green onions.', '6 large hard boiled eggs; 2 tablespoons butter; 2 tablespoons all-purpose flour; 1 1/2 cups milk; 1/2 cup heavy cream, plus more as needed; 1 teaspoon hot sauce, plus more for serving if desired; salt and freshly ground black pepper to taste; 4 slices bread, toasted, for serving; 2 green onions, thinly sliced; 6 slices bacon, cooked crisp and crumbled.', 'Cut eggs in half and separate yolks from whites. Chop egg whites and set aside. Set yolk halves aside. Melt butter in a saucepan over medium-high heat. Whisk in flour and cook, stirring constantly, 1 minute. Whisk in milk and cream and bring mixture to a boil, stirring constantly. Reduce heat to a simmer. Add hot sauce and salt and pepper to taste. Simmer, stirring often, 3 to 5 minutes. Add chopped egg whites and cook until heated through. Divide creamed eggs over toast. Use a microplane to grate egg yolks evenly over the top or crumble finely with fingers over the top. Top with green onions, crumbled bacon, and more hot sauce.', 'Old Fashioned Creamed Goldenrod Eggs breakfast warm creamy toast grated egg yolk crispy bacon green onions hard boiled eggs butter all purpose flour milk heavy cream hot sauce salt black pepper bread toasted green onions bacon calories protein fat carbs cooking instructions cut eggs melt butter whisk flour milk cream simmer chopped egg whites', '2026-05-09 04:38:33'),
(4, '3-Ingredient Pancakes (Easy High-Protein Breakfast!)', 'Breakfast', 15, '3 Servings', '/assets/img/recipes/breakfast/b2.jpg', '/recipes/breakfast/B2.html', 'These 3-ingredient pancakes are so tasty. They are light and fluffy and super easy to make.', '3 large eggs; 3/4 cup cottage cheese; 3/4 cup self-rising flour; cooking spray.', 'Combine eggs, cottage cheese, and flour in a blender. Blend until smooth. Heat a nonstick skillet or griddle over medium heat. Coat with nonstick spray. Drop 3-tablespoon portions of batter onto the skillet. Cook until edges are set, 1 to 2 minutes. Carefully turn and cook until bottoms are browned, 1 to 2 minutes. Serve with desired toppings, such as maple syrup, jam, fresh berries, or powdered sugar.', '3 Ingredient Pancakes Easy High Protein Breakfast pancakes light fluffy simple quick eggs cottage cheese self rising flour cooking spray maple syrup jam fresh berries powdered sugar blender skillet griddle breakfast protein', '2026-05-09 04:38:33'),
(5, 'Berry Cottage Cheese Breakfast Bowl', 'Breakfast', 5, '1 Serving', '/assets/img/recipes/breakfast/b3.jpg', '/recipes/breakfast/B3.html', 'This berry cottage cheese breakfast bowl is simple, nourishing, refreshing, filling, and beautiful to look at.', '1/2 cup low-fat cottage cheese; 2 large strawberries, sliced; 3 raspberries; 3 blackberries; 1 tablespoon pistachios, roughly chopped; 1 teaspoon flaxseed; 1 tablespoon honey.', 'Place cottage cheese into a small bowl. Arrange strawberries, raspberries, blackberries, pistachios, and flaxseed side-by-side on top. Drizzle with honey.', 'Berry Cottage Cheese Breakfast Bowl simple nourishing refreshing filling berries pistachios flaxseed low fat cottage cheese strawberries raspberries blackberries honey healthy breakfast protein bowl', '2026-05-09 04:38:33'),
(6, 'Banana Bread French Toast', 'Breakfast', 15, '4 to 6 Servings', '/assets/img/recipes/breakfast/b4.jpg', '/recipes/breakfast/B4.html', 'Banana bread is used as the base for this delicious French toast variation. Serve with extra banana slices and pecans.', '1 loaf banana bread; 3 large eggs; 1 cup milk; 1/4 cup all-purpose flour; 1 tablespoon ground cinnamon; 1 tablespoon white sugar; 1 teaspoon vanilla bean extract; 1 pinch salt; 2 tablespoons unsalted butter; 2 bananas, sliced, or more as needed; 1/4 cup chopped pecans; 1/4 cup syrup; 1/4 cup confectioners sugar.', 'Slice banana bread loaf into 3/4- to 1-inch thick slices. Whisk eggs, milk, flour, cinnamon, sugar, vanilla extract, and salt together in a bowl. Dip each banana bread slice into egg mixture. Heat butter in a large skillet over medium heat. Toast slices until golden brown, 3 to 4 minutes per side. Serve immediately with banana slices, chopped pecans, syrup, and confectioners sugar.', 'Banana Bread French Toast banana bread eggs milk all purpose flour cinnamon white sugar vanilla extract salt butter bananas pecans syrup confectioners sugar breakfast toast sweet', '2026-05-09 04:38:33'),
(7, 'One Pot Spicy Eggs and Potatoes', 'Breakfast', 55, '4 Servings', '/assets/img/recipes/breakfast/b5.jpg', '/recipes/breakfast/B5.html', 'One-Pot Spicy Eggs and Potatoes with homemade tomato simmer sauce, kale, potatoes, eggs, and creamy goat cheese.', '2 tablespoons olive oil, divided; 1/2 white onion, roughly chopped; 3 cloves garlic, minced; 3 teaspoons ancho chili powder, divided; 1 teaspoon salt; 1/2 cup chicken or vegetable broth; 1 28-ounce can tomatoes; 5 to 6 eggs; 1 cup diced potatoes; 2 cups kale, chopped finely; 4 ounces goat cheese.', 'Heat one tablespoon oil in a deep pot over medium heat. Add onions and saute until very soft. Add garlic, salt, two teaspoons chili powder, broth, and tomatoes. Simmer for 10 to 15 minutes, then blend until smooth. In the same pot, heat remaining oil over medium heat. Add potatoes and remaining chili powder. Saute until lightly browned. Add sauce back and simmer for 10 minutes. Stir in kale. Make holes and crack eggs into sauce. Cover and cook on low for 10 minutes, then rest 5 minutes. Top with goat cheese and serve.', 'One Pot Spicy Eggs and Potatoes homemade tomato simmer sauce kale potatoes eggs creamy goat cheese olive oil white onion garlic ancho chili powder salt chicken broth vegetable broth tomatoes diced potatoes kale goat cheese spicy breakfast one pot', '2026-05-09 04:38:33'),
(8, 'Ooey Gooey Chocolate Pudding Cake', 'Desserts', 115, '12 Servings', '/assets/img/recipes/desserts/ds1.jpg', '/recipes/desserts/DS1.html', 'Moist, fudgy yet fluffy chocolate pudding cake with a rich texture and irresistible flavor that will have you wanting seconds.', 'Cooking spray; 3/4 cup semisweet chocolate chips; 1 box Devil\'s food cake mix; 1 box chocolate instant pudding mix; 1 cup sour cream; 4 large eggs; 1/2 cup butter, melted; 1/2 cup water; 6 tablespoons butter, softened; 3 cups confectioners sugar; 5 tablespoons milk; 1 teaspoon vanilla extract; 1/4 cup cocoa powder.', 'Preheat the oven to 350 degrees F and grease a Bundt cake pan. Chop the chocolate chips and set aside. Combine cake mix, pudding mix, sour cream, eggs, melted butter, and water. Beat until creamy, then fold in chocolate chips. Pour batter into the pan and spread evenly. Bake for 40 to 44 minutes until a toothpick comes out clean. Cool 10 minutes, then invert and cool completely. Mix butter, sugar, milk, vanilla, and cocoa until smooth and creamy. Frost the cooled cake, slice, and serve.', 'Ooey Gooey Chocolate Pudding Cake desserts chocolate pudding cake moist fudgy fluffy semisweet chocolate chips Devils food cake mix chocolate instant pudding sour cream eggs butter water confectioners sugar milk vanilla cocoa powder frosting bundt cake', '2026-05-09 04:45:48'),
(9, 'No-Bake Lemon Bars', 'Desserts', 255, '16 Servings', '/assets/img/recipes/desserts/ds2.jpg', '/recipes/desserts/DS2.html', 'Fluffy, creamy no-bake lemon bars with a buttery shortbread crust and a bright, intense lemon flavor.', '1 1/2 cups shortbread crumbs; 1/4 cup unsalted butter, melted; 2 tablespoons white sugar; 1/2 teaspoon salt; 1 can sweetened condensed milk; 2 tablespoons lemon zest; 1/2 cup lemon juice; 1 1/2 cups heavy cream.', 'Line an 8x8-inch pan with parchment paper and set aside. Mix shortbread crumbs, melted butter, sugar, and salt, then press firmly into the bottom of the pan. Whisk together condensed milk, lemon zest, lemon juice, and salt until smooth. Beat heavy cream until stiff peaks form, then gently fold into the lemon mixture. Spread filling over crust and refrigerate for at least 4 hours until firm. Lift from pan, cut into bars, garnish with lemon zest, and serve.', 'No Bake Lemon Bars desserts lemon bars fluffy creamy no bake buttery shortbread crust lemon flavor shortbread crumbs unsalted butter white sugar salt sweetened condensed milk lemon zest lemon juice heavy cream refrigerator', '2026-05-09 04:45:48'),
(10, 'Two Huge Chocolate Chip Cookies', 'Desserts', 15, '2 Servings', '/assets/img/recipes/desserts/ds3.jpg', '/recipes/desserts/DS3.html', 'Just two thick, buttery chocolate chip cookies with crisp edges and a soft, gooey center that melts in your mouth.', '3 tablespoons butter; 3 tablespoons brown sugar; 1 1/2 tablespoons white sugar; 1/4 teaspoon vanilla; 1 egg yolk; 1/3 cup plus 2 tablespoons flour; 1 teaspoon cornstarch; 1/4 teaspoon baking soda; 1/4 teaspoon salt; 1/4 cup chocolate chips.', 'Preheat the oven to 350 degrees. Mix butter, brown sugar, white sugar, vanilla, and egg yolk until combined. Stir in flour, cornstarch, baking soda, and salt, then mix in chocolate chips to form a soft dough. Divide dough into two balls and place on a baking sheet. Bake for 10 to 12 minutes, then let cookies rest for a few minutes before serving.', 'Two Huge Chocolate Chip Cookies desserts cookies chocolate chip thick buttery crisp edges soft gooey center butter brown sugar white sugar vanilla egg yolk flour cornstarch baking soda salt chocolate chips dough bake', '2026-05-09 04:45:48'),
(11, 'Party Brownies', 'Desserts', 55, '12 Servings', '/assets/img/recipes/desserts/ds4.jpg', '/recipes/desserts/DS4.html', 'Brownies topped with a thick fudge frosting and colorful sprinkles, an easy and fun way to upgrade a box mix.', '1 box brownie mix; 6 tablespoons butter; 1/3 cup milk; 1 1/4 cups granulated sugar; 1 teaspoon vanilla extract; 1/2 teaspoon coarse kosher salt; 1 cup semi-sweet chocolate chips; rainbow sprinkles.', 'Bake the brownies according to package directions in a pan and let them cool. Melt butter in a saucepan, then add milk, sugar, vanilla, and salt. Bring to a boil and cook for 45 seconds. Remove from heat and stir in chocolate chips until smooth. Pour frosting over brownies, spread evenly, and add sprinkles. Let frosting set, then cut into squares and serve.', 'Party Brownies desserts brownies fudge frosting colorful sprinkles brownie mix butter milk granulated sugar vanilla extract kosher salt semi sweet chocolate chips rainbow sprinkles chocolate frosting', '2026-05-09 04:45:48'),
(12, 'House Favorite Cinnamon Rolls', 'Desserts', 740, '8 Servings', '/assets/img/recipes/desserts/ds5.jpg', '/recipes/desserts/DS5.html', 'Soft, pillowy cinnamon rolls made with brioche dough and topped with rich cream cheese frosting in every bite.', '1/2 cup lukewarm water; 1 teaspoon instant yeast; 1 teaspoon kosher salt; 1/2 cup butter, melted; 2 eggs; 3 tablespoons honey; 2 1/2 cups flour; 3 tablespoons butter, melted; 5 tablespoons white sugar; 5 tablespoons brown sugar; 1 teaspoon cinnamon; 2 ounces cream cheese; 2 tablespoons butter; 1/3 cup powdered sugar; 2 tablespoons milk; 1/4 teaspoon vanilla extract; pinch of salt.', 'Mix water and yeast in a bowl. Add melted butter, honey, eggs, salt, and flour and mix to form a sticky dough. Cover and let the dough rise at room temperature for 1 to 2 hours until doubled. Deflate dough gently and refrigerate for at least 3 hours until easier to handle. Roll chilled dough into a rectangle and brush with melted butter. Sprinkle with sugars and cinnamon evenly over the dough. Roll into a log and cut into 8 rolls, then place in a baking dish. Let rolls rise again in a warm oven for 45 minutes, then bake at 350 degrees for 20 to 22 minutes. Mix cream cheese, butter, powdered sugar, vanilla, milk, and salt until smooth. Spread frosting over warm rolls and serve.', 'House Favorite Cinnamon Rolls desserts cinnamon rolls soft pillowy brioche dough cream cheese frosting water yeast salt butter eggs honey flour white sugar brown sugar cinnamon cream cheese powdered sugar milk vanilla frosting', '2026-05-09 04:45:48'),
(13, 'Million Dollar Mac and Cheese', 'Dinner', 75, '10 Servings', '/assets/img/recipes/dinner/d1.jpg', '/recipes/dinner/D1.html', 'This rich and creamy mac and cheese is loaded with multiple cheeses, a smooth sauce, and a crispy buttery topping.', '8 tablespoons unsalted butter; 1 1/2 cups crushed crackers; 1/4 cup all-purpose flour; 2 1/2 cups whole milk; 1 1/2 cups half and half; 4 teaspoons Dijon mustard; 2 teaspoons salt; 1 teaspoon garlic powder; 1/4 teaspoon smoked paprika; vegetable bouillon cube; Cheddar cheese; smoked Cheddar cheese; Colby-Jack cheese; cavatappi pasta; mozzarella cheese; sour cream; fresh chives.', 'Preheat oven to 350 degrees F and grease a baking dish. Toast crushed crackers with butter in a skillet, then set aside. Cook flour and butter in a pot until lightly toasted. Add milk and half-and-half, whisking until thickened. Mix in mustard, salt, garlic powder, paprika, and bouillon. Add cheeses gradually and stir until melted and smooth. Stir in cooked pasta and spread half into baking dish. Add cheese and sour cream layers, then remaining pasta. Top with remaining cheese and cracker mixture. Bake for 25 to 30 minutes until bubbly, let rest, garnish with chives, and serve.', 'Million Dollar Mac and Cheese dinner mac cheese macaroni pasta cavatappi cheddar smoked cheddar Colby Jack mozzarella sour cream milk half and half butter flour crackers Dijon mustard garlic powder smoked paprika chives creamy baked', '2026-05-09 04:46:34'),
(14, 'Easy Slow Cooker Lasagna Soup', 'Dinner', 300, '6 Servings', '/assets/img/recipes/dinner/d2.jpg', '/recipes/dinner/D2.html', 'This slow cooker lasagna soup has all the flavors you love from lasagna, thrown together without all the work and cleanup.', '1 pound ground beef; 1 green bell pepper, chopped; 1 medium onion, chopped; 1 can diced tomatoes; 1 can crushed tomatoes; 1 carton beef broth; 1 can sliced mushrooms; 2 teaspoons Italian seasoning; 5 lasagna noodles; 1/2 cup mozzarella cheese; ricotta cheese optional; salt and black pepper.', 'Cook ground beef in a skillet over medium heat for 5 minutes, then drain. Place beef in slow cooker and add bell pepper, onion, tomatoes, broth, mushrooms, and seasoning. Cook on low for 4 hours. Add broken lasagna noodles and cook until tender, about 45 minutes. Season with salt and pepper. Serve in bowls, top with mozzarella and ricotta cheese.', 'Easy Slow Cooker Lasagna Soup dinner lasagna soup ground beef bell pepper onion diced tomatoes crushed tomatoes beef broth mushrooms Italian seasoning lasagna noodles mozzarella ricotta cheese slow cooker comfort meal', '2026-05-09 04:46:34'),
(15, 'Thai Shrimp Curry with Shallot Crispies', 'Dinner', 25, '4 Servings', '/assets/img/recipes/dinner/d3.jpg', '/recipes/dinner/D3.html', 'This shrimp curry is full of incredible flavor, made with simple ingredients and perfect for a quick weeknight dinner.', '1 tablespoon avocado oil; 2 tablespoons red curry paste; 2 cloves garlic; fresh ginger; 2 cups vegetables; 1 can coconut milk; 1 pound shrimp; 1 tablespoon fish sauce; 1 tablespoon brown sugar; avocado oil for crispies; shallots; panko breadcrumbs; cilantro or Thai basil.', 'Heat oil and cook shallots until golden, then add panko and cook until crispy. Set aside with herbs. Wipe the pan and cook oil, curry paste, garlic, ginger, and vegetables for a few minutes. Add coconut milk and simmer until slightly thickened and vegetables are tender. Add shrimp and cook for 2 to 3 minutes per side until fully cooked. Stir in fish sauce and sugar, adjust seasoning, then serve over rice with shallot crispies.', 'Thai Shrimp Curry with Shallot Crispies dinner shrimp curry coconut milk red curry paste garlic fresh ginger vegetables fish sauce brown sugar shallots panko breadcrumbs cilantro Thai basil rice spicy seafood', '2026-05-09 04:46:34'),
(16, 'Smash Burgers with House Sauce', 'Dinner', 35, '4 Servings', '/assets/img/recipes/dinner/d4.jpg', '/recipes/dinner/D4.html', 'The famous smash burger with deeply crisped, juicy patties covered with melty cheese, piled on a buttery bun, and topped with house sauce.', '4 tablespoons butter, melted; 1 tablespoon Worcestershire sauce; 1 teaspoon fish sauce; 1 teaspoon smoked paprika; 1 pound ground beef; 4 brioche buns; 4 slices American cheese; house sauce; 1/2 onion, diced or sliced; 4 lettuce leaves; 1 tomato; 12 pickle slices.', 'Mix melted butter, Worcestershire sauce, fish sauce, and smoked paprika in a bowl. Add to ground beef, mix well, form into 4 balls, and chill for 20 to 30 minutes. Butter the buns and toast them on a skillet or griddle until golden. Prepare the toppings and house sauce, and cut small pieces of parchment paper for smashing the burgers. Heat a cast iron skillet or griddle until very hot. Place burger balls on the surface, sprinkle with salt, and let them sizzle for about 20 seconds. Place parchment paper on top and smash the burgers flat. Cook for a few minutes, then flip and top with cheese. Cook another 1 to 2 minutes until cheese melts. Assemble the burgers with toasted buns, smash burger patties, cheese, lettuce, and house sauce, then serve.', 'Smash Burgers with House Sauce dinner burger beef ground beef brioche buns American cheese Worcestershire sauce fish sauce smoked paprika butter onion lettuce tomato pickles house sauce skillet griddle', '2026-05-09 04:46:34'),
(17, 'Creamy Mushroom Soup', 'Dinner', 35, '4 Servings', '/assets/img/recipes/dinner/d5.jpg', '/recipes/dinner/D5.html', 'A creamy mushroom soup with earthy mushrooms, velvety broth, onions, garlic, white wine, and cream.', '3 tablespoons butter; 1 tablespoon olive oil; 16 ounces mushrooms; 1 to 2 shallots, minced; 4 cloves garlic; 1/4 cup all-purpose flour; 1/2 cup white wine; 3 cups broth; 1/2 to 1 cup heavy cream; salt and black pepper; fresh thyme; sourdough bread for croutons; olive oil for croutons; garlic for croutons.', 'Prepare the croutons and set aside. Heat butter and oil in a pot, then saute mushrooms and shallots for about 10 minutes. Add garlic and cook briefly. Add flour and stir to coat, then gradually pour in wine and broth, stirring until smooth. Add cream, salt, pepper, and thyme. Let the soup sit over low heat without boiling. Serve warm with croutons on top.', 'Creamy Mushroom Soup dinner mushroom soup mushrooms cream heavy cream butter olive oil shallots garlic flour white wine broth thyme sourdough bread croutons creamy comfort soup', '2026-05-09 04:46:34'),
(18, 'Healthy Green Juice', 'Drinks', 10, '2 Servings', '/assets/img/recipes/drinks/dr1.jpg', '/recipes/drinks/DR1.html', 'A refreshing detox juice made with kale, cucumber, celery, apples, and ginger, perfect for a healthy boost.', '4 stalks celery; 2 green apples; 1 cucumber; 6 leaves kale; 1/2 lemon; 1 piece fresh ginger.', 'Gather all ingredients. Process celery, apples, cucumber, kale, lemon, and ginger through a juicer. Serve immediately or store in a jar in the fridge and shake before drinking.', 'Healthy Green Juice drinks detox juice kale cucumber celery green apples lemon fresh ginger refreshing healthy boost juicer', '2026-05-09 04:47:01'),
(19, 'Cool Watermelon Slushes', 'Drinks', 6, '4 Servings', '/assets/img/recipes/drinks/dr2.jpg', '/recipes/drinks/DR2.html', 'A refreshing Thailand-style watermelon slushie sweetened with honey for a light and cooling drink.', '6 ice cubes; 2 cups cubed watermelon; 1 teaspoon honey.', 'Crush the ice in a blender, then add watermelon and blend until slushy. Add honey and blend briefly before serving.', 'Cool Watermelon Slushes drinks watermelon slushie ice cubes cubed watermelon honey blender refreshing cold summer', '2026-05-09 04:47:01'),
(20, 'Pomegranate Fizz', 'Drinks', 5, '1 Serving', '/assets/img/recipes/drinks/dr3.jpg', '/recipes/drinks/DR3.html', 'A refreshing mocktail combining tart pomegranate juice, fresh basil, lime, and a bubbly splash of club soda.', '5 fresh basil leaves; 1 tablespoon agave syrup or honey; 1 fluid ounce lime juice; 3 fluid ounces pomegranate juice; 4 fluid ounces club soda; ice cubes; 1 lime wedge.', 'Mash basil with lime juice and agave in a shaker, then add pomegranate juice and shake well. Fill a glass with ice, strain the mixture, top with club soda, and garnish with a lime wedge.', 'Pomegranate Fizz drinks mocktail pomegranate juice fresh basil lime agave honey club soda ice lime wedge fizzy refreshing', '2026-05-09 04:47:01'),
(21, 'Iced Pumpkin Spice Latte', 'Drinks', 5, '1-2 Servings', '/assets/img/recipes/drinks/dr4.jpg', '/recipes/drinks/DR4.html', 'A quick and customizable iced pumpkin spice latte made with espresso, milk, maple syrup, and warm fall spices.', '1 shot espresso; 1 cup milk; 2 tablespoons maple syrup; 2 tablespoons pumpkin puree; 1/2 teaspoon vanilla extract; 1/4 teaspoon pumpkin pie spice; pinch of salt; ice; whipped cream optional.', 'Blend espresso, milk, maple syrup, pumpkin puree, vanilla, pumpkin spice, and salt until smooth. Pour over ice and serve cold, topped with whipped cream and extra spice if desired.', 'Iced Pumpkin Spice Latte drinks espresso milk maple syrup pumpkin puree vanilla extract pumpkin pie spice salt ice whipped cream coffee latte fall spices', '2026-05-09 04:47:01'),
(22, 'Instant Gingerbread Hot Chocolate', 'Drinks', 10, '20 Servings', '/assets/img/recipes/drinks/dr5.jpg', '/recipes/drinks/DR5.html', 'A cozy seasonal hot chocolate mix with warm gingerbread spices and a hint of molasses flavor.', '1 cup cocoa; 1 cup white sugar; 1/2 cup brown sugar; 2 teaspoons ground ginger; 1 teaspoon ground cinnamon; 1/4 teaspoon ground cloves; 1/4 teaspoon salt; pinch cayenne pepper optional.', 'Whisk cocoa, white sugar, brown sugar, ginger, cinnamon, cloves, salt, and cayenne together in a bowl. Store the mixture in an airtight container until ready to use. Heat milk until almost simmering and whisk in 2 tablespoons of the mix per cup of milk. Stir until fully dissolved, pour into mugs, and serve hot.', 'Instant Gingerbread Hot Chocolate drinks hot chocolate cocoa white sugar brown sugar ground ginger cinnamon cloves salt cayenne pepper milk gingerbread warm cozy seasonal', '2026-05-09 04:47:01'),
(23, 'Teriyaki Salmon Bowl', 'Lunch', 30, '1 Serving', '/assets/img/recipes/lunch/l1.jpg', '/recipes/lunch/L1.html', 'Salmon baked with a homemade teriyaki sauce using soy sauce, brown sugar, garlic, and ginger, then served with rice, red cabbage, carrots, and radishes.', '1/4 cup low-sodium soy sauce; 3 tablespoons brown sugar; 1 small clove garlic, chopped; 1 tablespoon chopped fresh ginger; 1 6-ounce salmon filet; 1/4 cup grated carrots; 2 radishes, thinly sliced; 1 cup shredded red cabbage; 1 cup cooked rice; 1 teaspoon sesame seeds optional; 1 green onion, thinly sliced optional.', 'Preheat the oven to 400 degrees F and spray a baking dish with cooking spray. Combine soy sauce, brown sugar, garlic, and ginger in a small bowl. Place the salmon in the prepared baking dish, skin side down, and pour the teriyaki sauce over. Bake until fish flakes easily with a fork, 12 to 15 minutes. Place rice in a bowl, top with salmon, and spoon over teriyaki sauce. Add cabbage, carrots, and radishes, then garnish with green onions and sesame seeds.', 'Teriyaki Salmon Bowl lunch salmon soy sauce brown sugar garlic ginger carrots radishes red cabbage rice sesame seeds green onion teriyaki sauce baked salmon bowl', '2026-05-09 04:47:25'),
(24, 'Pasta Salad', 'Lunch', 30, '6 Servings', '/assets/img/recipes/lunch/l2.jpg', '/recipes/lunch/L2.html', 'A colorful and easy pasta salad that is great for summer picnics or parties.', '1 pound tri-colored spiral pasta; 1 16-ounce bottle Italian-style salad dressing; 6 tablespoons salad seasoning mix; 2 cups cherry tomatoes, diced; 1 green bell pepper, chopped; 1 red bell pepper, diced; 1/2 yellow bell pepper, chopped; 1 2.25-ounce can black olives, chopped.', 'Gather all ingredients. Bring a large pot of lightly salted water to a boil. Cook pasta, stirring occasionally, until tender yet firm to the bite, about 10 to 12 minutes. Rinse under cold water and drain. Whisk Italian dressing and salad seasoning mix together until smooth. Combine pasta, tomatoes, bell peppers, and olives in a salad bowl. Pour dressing over salad and toss to coat. Refrigerate for 8 hours to overnight for best flavor, then serve.', 'Pasta Salad lunch pasta tri colored spiral pasta Italian dressing salad seasoning cherry tomatoes green bell pepper red bell pepper yellow bell pepper black olives summer picnic party cold salad', '2026-05-09 04:47:25'),
(25, 'Baked Potato Soup', 'Lunch', 40, '6 Servings', '/assets/img/recipes/lunch/l3.jpg', '/recipes/lunch/L3.html', 'A thick and creamy baked potato soup that is a great way to use leftover baked potatoes.', '12 slices bacon; 2/3 cup butter; 2/3 cup all-purpose flour; 7 cups milk; 4 large baked potatoes, peeled and cubed; 4 green onions, chopped; 1 1/4 cups shredded Cheddar cheese; 1 cup sour cream; 1 teaspoon salt; 1 teaspoon ground black pepper.', 'Gather all ingredients. Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned, about 8 to 10 minutes. Drain on paper towels, crumble, and set aside. Melt butter in a stockpot or Dutch oven over medium heat. Gradually add flour, whisking until well combined. Slowly pour in milk, whisking constantly until smooth and thickened. Add potatoes and onions and bring to a boil, stirring frequently. Reduce heat and simmer for 10 minutes. Stir in bacon, cheese, sour cream, salt, and pepper. Cook until cheese melts, then serve.', 'Baked Potato Soup lunch potato soup creamy thick bacon butter flour milk baked potatoes green onions Cheddar cheese sour cream salt black pepper cold weather comfort soup', '2026-05-09 04:47:25'),
(26, 'Philly Cheesesteak', 'Lunch', 40, '4 Servings', '/assets/img/recipes/lunch/l4.jpg', '/recipes/lunch/L4.html', 'A flavorful Philly cheesesteak made with seasoned sirloin, caramelized onions, peppers, cheese, and toasted hoagie rolls.', '1/2 teaspoon salt; 1/2 teaspoon black pepper; 1/2 teaspoon paprika; 1/2 teaspoon chili powder; 1/2 teaspoon onion powder; 1/2 teaspoon garlic powder; 1/2 teaspoon dried thyme; 1/2 teaspoon dried marjoram; 1/2 teaspoon dried basil; 1 pound beef sirloin; 3 tablespoons vegetable oil; 1 onion, sliced; 1 green bell pepper, julienned; 3 ounces Swiss cheese; 4 hoagie rolls.', 'Gather all ingredients. Mix all seasonings together in a small bowl. Place steak in a bowl and coat with seasoning mixture. Heat half the oil in a skillet and cook steak until browned, then set aside. Heat remaining oil and cook onion and green pepper until tender. Preheat oven to broil setting. Divide beef between rolls and top with onion and peppers. Add cheese and place on a baking sheet. Broil until cheese melts, then close sandwiches and serve.', 'Philly Cheesesteak lunch cheesesteak sandwich beef sirloin salt black pepper paprika chili powder onion powder garlic powder thyme marjoram basil vegetable oil onion green bell pepper Swiss cheese hoagie rolls', '2026-05-09 04:47:25'),
(27, 'Buffalo Chicken Bowls with Cauliflower Garlic Rice', 'Lunch', 40, '4 Servings', '/assets/img/recipes/lunch/l5.jpg', '/recipes/lunch/L5.html', 'Buffalo chicken bowls with spicy buffalo chicken, rice and cauliflower rice, tomatoes, cucumbers, and creamy dill dip.', '1 pound chicken breast fillets; 1/4 cup hot sauce; 2 tablespoons honey; 1 teaspoon garlic powder; 1 teaspoon paprika; 1 teaspoon salt; 1/2 teaspoon onion powder; black pepper to taste; 1 cup white rice; 1 package riced cauliflower; 1 to 2 tablespoons olive oil; cucumbers, sliced; cherry tomatoes, halved; dill dip or dressing.', 'Place chicken, hot sauce, honey, garlic powder, paprika, salt, onion powder, and black pepper in a bowl and marinate for 30 minutes to 2 hours. Cook rice according to package directions. Place cauliflower rice on a sheet pan, drizzle with olive oil, season with salt, and roast at 425 degrees F for 20 to 30 minutes. Mix with cooked rice. Cook chicken in a hot pan until browned and fully cooked. Let rest for a few minutes. Slice chicken and serve with rice mixture, cucumbers, tomatoes, and a dollop of dressing.', 'Buffalo Chicken Bowls with Cauliflower Garlic Rice lunch buffalo chicken hot sauce honey garlic powder paprika salt onion powder black pepper white rice riced cauliflower olive oil cucumbers cherry tomatoes dill dip dressing meal prep spicy chicken bowl', '2026-05-09 04:47:25'),
(28, 'Cowboy Butter Snack Mix', 'Snacks', 30, '15 to 20 Servings', '/assets/img/recipes/snacks/s1.jpg', '/recipes/snacks/S1.html', 'A flavorful snack mix made with mini crackers, pretzels, corn nuts, and crunchy corn snacks slowly baked in smoky cowboy-seasoned butter.', '2 cups bite-size Cheddar cheese crackers; 1 cup ranch-flavored Corn Nuts; 2 cups Nacho Bugles; 2 cups Goldfish crackers; 2 cups mini saltine crackers; 1 cup mini pretzel twists; 1 ounce packet ranch dressing mix; 1/2 cup butter, melted; 1 tablespoon Worcestershire sauce; 1 teaspoon crushed red pepper; 2 teaspoons smoked paprika; 2 teaspoons dry mustard; 1 teaspoon garlic powder; 1/4 teaspoon freshly ground black pepper.', 'Gather all ingredients. Preheat the oven to 250 degrees F. Combine cheese crackers, corn nuts, Nacho Bugles, Goldfish crackers, mini saltines, mini pretzels, ranch dressing mix, melted butter, Worcestershire sauce, red pepper, smoked paprika, dry mustard, garlic powder, and black pepper in a large bowl until evenly coated. Transfer to a large rimmed baking sheet and spread into an even layer. Bake until lightly toasted and mostly dry, 20 to 25 minutes, stirring once halfway through.', 'Cowboy Butter Snack Mix snacks crackers pretzels corn nuts Cheddar cheese crackers ranch Corn Nuts Nacho Bugles Goldfish crackers mini saltines mini pretzel twists ranch dressing butter Worcestershire sauce crushed red pepper smoked paprika dry mustard garlic powder black pepper party snack', '2026-05-09 04:47:50'),
(29, 'Salted Pretzel Church Window Cookies', 'Snacks', 290, '44 Servings', '/assets/img/recipes/snacks/s2.jpg', '/recipes/snacks/S2.html', 'A classic sweet no-bake treat with salty pretzels, roasted mixed nuts, marshmallows, and dark chocolate.', '2 1/4 cups salted roasted mixed nuts; 1/2 cup butter; 1 cup semisweet chocolate chips; 1 cup dark chocolate chips; 5 cups rainbow miniature marshmallows; 1 1/2 cups pretzels, crushed.', 'Coarsely chop 1 1/2 cups nuts and finely chop remaining nuts. Melt butter in a double boiler or heat-safe bowl set over simmering water, then add semisweet and dark chocolate chips. Heat and stir until melted, then remove from heat and cool for 10 minutes. Add marshmallows and coarsely chopped nuts to the chocolate mixture and stir gently to coat. Spoon mixture onto parchment paper and shape into logs. Chill until slightly firm. Combine finely chopped nuts and crushed pretzels, then roll the chilled logs in the pretzel mixture. Wrap tightly and chill until firm, at least 4 hours. Cut into slices and serve.', 'Salted Pretzel Church Window Cookies snacks no bake cookies pretzels salted roasted mixed nuts butter semisweet chocolate chips dark chocolate chips rainbow miniature marshmallows sweet salty chocolate marshmallow pretzel', '2026-05-09 04:47:50'),
(30, 'No-Bake Energy Bites', 'Snacks', 75, '24 Servings', '/assets/img/recipes/snacks/s3.jpg', '/recipes/snacks/S3.html', 'Healthy no-bake energy bites made with oats, chocolate chips, flax seed, peanut butter, honey, and vanilla.', '1 cup rolled oats; 1/2 cup miniature semisweet chocolate chips; 1/2 cup ground flax seed; 1/2 cup crunchy peanut butter; 1/3 cup honey; 1 teaspoon vanilla extract.', 'Gather all ingredients. Stir oats, chocolate chips, flax seed, peanut butter, honey, and vanilla extract together in a bowl. Roll the dough into 24 balls with your hands. Arrange balls on a baking sheet and freeze until set, about 1 hour. Serve and enjoy.', 'No Bake Energy Bites snacks healthy energy bites rolled oats miniature semisweet chocolate chips ground flax seed crunchy peanut butter honey vanilla extract no bake quick snack protein', '2026-05-09 04:47:50'),
(31, 'Mixed Berry Muffins', 'Snacks', 30, '10 Servings', '/assets/img/recipes/snacks/s4.jpg', '/recipes/snacks/S4.html', 'Fluffy mixed berry muffins topped with crunchy sugar and served with honey butter.', '3/4 cup coconut oil, melted; 1/2 cup brown sugar; 1/4 cup maple syrup; 1/4 cup plain Greek yogurt; 2 eggs; 1 1/2 teaspoons vanilla; 2 cups flour; 2 1/2 teaspoons baking powder; 1/2 teaspoon baking soda; 1 teaspoon fine kosher salt; 2 cups frozen mixed berries; 1/4 cup turbinado sugar; 4 tablespoons softened salted butter; 1/4 cup honey.', 'Preheat the oven to 400 degrees. Whisk coconut oil, brown sugar, maple syrup, yogurt, eggs, and vanilla together until smooth. Add flour, baking powder, baking soda, and salt and stir to form a soft dough. Microwave frozen berries for one minute, then transfer to a strainer, rinse with warm water, and drain well. Gently fold berries into the batter with minimal stirring. Grease a muffin tin and divide batter between 9 to 10 cups. Top with turbinado sugar. Bake for 14 to 16 minutes until golden. Mix butter with honey if desired and serve with warm muffins.', 'Mixed Berry Muffins snacks muffins mixed berries coconut oil brown sugar maple syrup Greek yogurt eggs vanilla flour baking powder baking soda kosher salt frozen mixed berries turbinado sugar salted butter honey berry muffin', '2026-05-09 04:47:50'),
(32, '30 Minute Sesame Roasted Sweet Potatoes', 'Snacks', 30, '4 Servings', '/assets/img/recipes/snacks/s5.jpg', '/recipes/snacks/S5.html', 'Healthy sesame roasted sweet potatoes topped with tahini, sesame oil, cilantro, and sesame seeds.', '2 sweet potatoes, peeled and cut into wedges; 1 tablespoon vegetable oil; 1/2 teaspoon chili powder; pinch of cayenne pepper for spiciness; salt and pepper; 2 tablespoons roasted sesame oil; 2 tablespoons tahini; 2 tablespoons sesame seeds; fresh cilantro.', 'Preheat the oven to 375 degrees. Toss sweet potatoes with vegetable oil, chili powder, cayenne, salt, and pepper. Place on a baking sheet and roast for 20 minutes, stirring gently every 5 to 10 minutes. Increase heat to 400 degrees and roast for another 5 to 10 minutes until golden brown. Remove from the oven and let cool slightly. Drizzle sweet potatoes with sesame oil and tahini. Sprinkle with sesame seeds and cilantro, then serve immediately.', '30 Minute Sesame Roasted Sweet Potatoes snacks sweet potatoes vegetable oil chili powder cayenne pepper salt pepper roasted sesame oil tahini sesame seeds fresh cilantro healthy roasted', '2026-05-09 04:47:50');

CREATE TABLE `users` (
  `id` int(11) NOT NULL,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `username` varchar(50) NOT NULL,
  `bio` varchar(255) DEFAULT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `contacts`
  ADD PRIMARY KEY (`id`);
  
ALTER TABLE `favorites`
  ADD PRIMARY KEY (`id`),
  ADD KEY `user_id` (`user_id`),
  ADD KEY `fk_favorites_site_recipe` (`site_recipe_id`);
  
ALTER TABLE `recipes`
  ADD PRIMARY KEY (`id`),
  ADD KEY `user_id` (`user_id`);
  
ALTER TABLE `site_recipes`
  ADD PRIMARY KEY (`id`);
  
ALTER TABLE `users`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `username` (`username`),
  ADD UNIQUE KEY `email` (`email`);
  
ALTER TABLE `contacts`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1;
  
ALTER TABLE `favorites`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1;
  
ALTER TABLE `recipes`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1;
  
ALTER TABLE `site_recipes`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=33;
  
ALTER TABLE `users`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1;
  
ALTER TABLE `favorites`
  ADD CONSTRAINT `favorites_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `fk_favorites_site_recipe` FOREIGN KEY (`site_recipe_id`) REFERENCES `site_recipes` (`id`) ON DELETE CASCADE;
  
ALTER TABLE `recipes`
  ADD CONSTRAINT `recipes_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL;
